Inject `IServiceScopeFactory` into the Singleton and create a scope per read:

```csharp
public sealed class OrderCacheService(IServiceScopeFactory scopeFactory)
{
    private readonly IServiceScopeFactory _scopeFactory = scopeFactory;

    public async Task<Order?> GetOrderAsync(Guid id, CancellationToken ct = default)
    {
        await using var scope = _scopeFactory.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<OrderDbContext>();
